SELECT COUNT(*) AS cantidad_parques_solares, COLLECT_LIST(park_name) AS parques, COLLECT_LIST(province) AS provincias
FROM andes_viento_dev.gold.dim_park
WHERE technology = 'Solar' AND park_name IS NOT NULL AND province IS NOT NULL;

SELECT COUNT(*) AS contratos_vigentes
FROM `andes_viento_dev`.`gold`.`dim_contract`
WHERE `status` = 'VIGENTE' AND `is_current` = true AND `contract_key` <> -1;
